package cn.academy.port.fleet;
import com.mojang.brigadier.arguments.*;
import net.minecraft.commands.Commands;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.neoforge.event.RegisterCommandsEvent;
/** Destructive fixtures are registered only in explicitly authorized disposable QA worlds. */
public final class FleetQa {
 private static LabVehicle nearest(ServerPlayer p){if(p.getVehicle() instanceof LabVehicle v)return v;return p.serverLevel().getEntitiesOfClass(LabVehicle.class,p.getBoundingBox().inflate(40)).stream().min(java.util.Comparator.comparingDouble(v->v.distanceToSqr(p))).orElseThrow();}
 private static int sideView(ServerPlayer p){LabVehicle v=nearest(p);p.stopRiding();double distance=Math.max(4.5,v.config().length*.7);var at=v.localToWorld(new net.minecraft.world.phys.Vec3(-distance,2.2,distance*.75));var target=v.position().add(0,v.config().height*.5,0);var delta=target.subtract(at.add(0,p.getEyeHeight(),0));float yaw=(float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),pitch=(float)-Math.toDegrees(Math.atan2(delta.y,Math.sqrt(delta.x*delta.x+delta.z*delta.z)));p.teleportTo(p.serverLevel(),at.x,at.y,at.z,yaw,pitch);p.setNoGravity(true);return 1;}
 private static int total(ServerPlayer p,int v){int n=0;for(var s:p.getInventory().items){if(s.getItem() instanceof GunItem g&&g.variant==v)n+=GunItem.ammo(s);if(s.is(InteractionLab.magazine(v)))n+=CoilMagazineItem.energy(s);}for(var e:p.serverLevel().getEntitiesOfClass(ItemEntity.class,p.getBoundingBox().inflate(16)))if(e.getItem().is(InteractionLab.magazine(v)))n+=CoilMagazineItem.energy(e.getItem());return n;}
 private static int setup(ServerPlayer p,int v,String mode){CoilReloads.cancel(p);p.stopRiding();p.getInventory().clearContent();for(var e:p.serverLevel().getEntitiesOfClass(ItemEntity.class,p.getBoundingBox().inflate(16)))e.discard();p.getInventory().selected=0;var s=new ItemStack(InteractionLab.GUNS[v].get());GunItem.ammo(s,mode.equals("empty")?0:Math.min(5,InteractionLab.CAPS[v]-1));if(!mode.equals("legacy"))GunItem.hasMagazine(s,true);p.getInventory().setItem(0,s);if(!mode.equals("no_spare"))p.getInventory().setItem(1,CoilMagazineItem.create(v,InteractionLab.CAPS[v]));if(mode.equals("full"))for(int i=2;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));p.getPersistentData().putInt("fleet_variant",v);p.getPersistentData().putInt("fleet_expected",total(p,v));InteractionLab.LOGGER.info("FLEET_SETUP variant={} case={} total={}",v,mode,total(p,v));return 1;}
 private static int check(ServerPlayer p,String mode){int v=p.getPersistentData().getInt("fleet_variant"),expected=p.getPersistentData().getInt("fleet_expected"),actual=total(p,v);ItemStack gun=ItemStack.EMPTY;for(var s:p.getInventory().items)if(s.getItem() instanceof GunItem g&&g.variant==v)gun=s;boolean ok=expected==actual&&!CoilReloads.active(p);if(mode.equals("cancel_removed")||mode.equals("switch"))ok&=GunItem.ammo(gun)==0&&!GunItem.hasMagazine(gun);else if(mode.equals("cancel_before")||mode.equals("no_spare"))ok&=GunItem.ammo(gun)==Math.min(5,InteractionLab.CAPS[v]-1)&&GunItem.hasMagazine(gun);else ok&=GunItem.ammo(gun)==InteractionLab.CAPS[v]&&GunItem.hasMagazine(gun);InteractionLab.LOGGER.info("FLEET_ASSERT variant={} case={} pass={} expected={} actual={} loaded={} hasMag={}",v,mode,ok,expected,actual,GunItem.ammo(gun),GunItem.hasMagazine(gun));if(!ok)throw new IllegalStateException("Fleet magazine test "+v+" "+mode);return 1;}
 private static int car(ServerPlayer p,int v,int n){p.stopRiding();CoilReloads.cancel(p);p.getInventory().clearContent();for(var old:p.serverLevel().getEntitiesOfClass(LabVehicle.class,p.getBoundingBox().inflate(150)))old.discard();for(int i=0;i<n;i++){var vehicle=InteractionLab.CAR.get().create(p.serverLevel());vehicle.variant(v);vehicle.moveTo(p.getX()+(i%4)*4,p.getY(),p.getZ()+(i/4)*14,0,0);p.serverLevel().addFreshEntity(vehicle);if(i==0&&n==1)p.startRiding(vehicle);}InteractionLab.LOGGER.info("FLEET_CAR_SETUP variant={} count={} mounted={}",v,n,p.isPassenger());return 1;}
 private static int state(ServerPlayer p){if(!(p.getVehicle() instanceof LabVehicle v))throw new IllegalStateException("No mounted vehicle");InteractionLab.LOGGER.info("FLEET_CAR_STATE variant={} pos={} speed={} steering={} pitch={} roll={} eye={} seats={} dimensions={}",v.variant(),v.position(),v.speed(),v.steering(),v.bodyPitch(),v.bodyRoll(),v.config().eye,v.config().seats.size(),v.getBoundingBox());InteractionLab.LOGGER.info("FLEET_DRIVER_PLAYER position={} eye={} bbox={} height={}",p.position(),p.getEyePosition(),p.getBoundingBox(),p.getBbHeight());if(!Double.isFinite(v.getY())||!Float.isFinite(v.speed()))throw new IllegalStateException("Invalid vehicle state");return 1;}
 @SubscribeEvent public static void commands(RegisterCommandsEvent e){if(!Boolean.getBoolean("academy.qa.showcase")||!Boolean.getBoolean("academy.qa.confirmOwnWorld"))return;var d=e.getDispatcher();d.register(Commands.literal("aclab_qa_fleet").requires(s->s.hasPermission(2))
 .then(Commands.literal("setup").then(Commands.argument("gun",IntegerArgumentType.integer(1,6)).then(Commands.argument("case",StringArgumentType.word()).executes(c->setup(c.getSource().getPlayerOrException(),IntegerArgumentType.getInteger(c,"gun")-1,StringArgumentType.getString(c,"case"))))))
 .then(Commands.literal("assert").then(Commands.argument("case",StringArgumentType.word()).executes(c->check(c.getSource().getPlayerOrException(),StringArgumentType.getString(c,"case")))))
 .then(Commands.literal("switch").executes(c->{c.getSource().getPlayerOrException().getInventory().selected=8;return 1;}))
 .then(Commands.literal("car").then(Commands.argument("variant",IntegerArgumentType.integer(1,6)).then(Commands.argument("count",IntegerArgumentType.integer(1,16)).executes(c->car(c.getSource().getPlayerOrException(),IntegerArgumentType.getInteger(c,"variant")-1,IntegerArgumentType.getInteger(c,"count"))))))
 .then(Commands.literal("door").executes(c->{nearest(c.getSource().getPlayerOrException()).toggleDoor();return 1;}))
 .then(Commands.literal("sideview").executes(c->sideView(c.getSource().getPlayerOrException())))
 .then(Commands.literal("state").executes(c->state(c.getSource().getPlayerOrException()))));}
}
